  ["ce7919957730ed0e"] = { "Per il Dark Strand!", "." },
  ["ce89390ef9733ace"] = { "Il tuo compito è concluso. Preparati ad affrontare il tuo destino.", "." },
  ["ce8a7e75b96209c6"] = { "Ti serve l'aiuto di Bulrug. Lo troverai all'aperto, sull'altura inferiore, tra la locanda e la banca di ⟦Thunder Bluff=Picco del Tuono⟧.", "." },
